// captureLogs swaps the default slog logger for one writing to the returned
// buffer (the decision_log_test precedent) and restores it on cleanup.
func captureLogs(t *testing.T) *strings.Builder {
	t.Helper()
	var buf strings.Builder
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })
	return &buf
}

// beaconLines returns the captured INFO lines carrying the beacon message.
func beaconLines(buf *strings.Builder) []string {
	var lines []string
	for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
		if strings.Contains(ln, `msg="playback event"`) {
			lines = append(lines, ln)
		}
	}
	return lines
}

// mintClientToken pairs one device through the real flow (create → approve →
// wait) and returns the minted RoleClient credential (the artTestApp
// precedent, inlined: this is the TV's voice for the browse-group test).
func mintClientToken(t *testing.T, h http.Handler) string {
	t.Helper()
	create := doRequest(t, h, http.MethodPost, "/api/v1/pair", "", "")
	defer create.Body.Close()
	var pr pairCreateResponse
	if err := json.NewDecoder(create.Body).Decode(&pr); err != nil {
		t.Fatalf("decode pair create: %v", err)
	}
	approve := doRequest(t, h, http.MethodPost, "/api/v1/admin/pairings/"+pr.PairingID+"/approve", "", adminToken)
	defer approve.Body.Close()
	if approve.StatusCode != http.StatusOK {
		t.Fatalf("approve = %d, want 200", approve.StatusCode)
	}
	wait := doRequest(t, h, http.MethodGet, "/api/v1/pair/"+pr.PairingID+"/wait", "", "")
	defer wait.Body.Close()
	var wr pairWaitResponse
	if err := json.NewDecoder(wait.Body).Decode(&wr); err != nil {
		t.Fatalf("decode pair wait: %v", err)
	}
	if wr.DeviceToken == "" {
		t.Fatalf("approved pairing carried no device token: %+v", wr)
	}
	return wr.DeviceToken
}

// wellFormed is a canonical beacon payload reused across the happy paths.
const wellFormed = `{"item_id":"itm_unknown","mode":"direct","phase":"video-error","code":"MEDIA_ERR_SRC_NOT_SUPPORTED","detail":"video error on the direct floor"}`

// TestPlaybackEvents is the spec floor for "Playback event beacon"
// (tv-playback-unblock D7): a well-formed beacon answers 204 with no body
// and its ENTIRE effect is one INFO line (five fields + truncated detail +
// UA); malformed shapes answer the canonical 400; the per-client in-process
// limit trips to 429 rate_limited and logs nothing for the rejected ones;
// a client-role (pairing-minted) session is accepted like an admin one; no
// auth 401s via the standard middleware; and no store is ever read.
func TestPlaybackEvents(t *testing.T) {
	newHandler := func(st *store.Store) http.Handler {
		deps := Deps{AdminToken: adminToken, Pairing: pairing.NewService(st, nil)}
		if st != nil {
			deps.Store = st
		}
		return New(deps)
	}

	t.Run("well_formed_beacon_204_one_info_line", func(t *testing.T) {
		buf := captureLogs(t)
		resp := doRequest(t, newHandler(openAPIStore(t)), http.MethodPost, "/api/v1/playback-events", wellFormed, adminToken)
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("status = %d, want 204", resp.StatusCode)
		}
		if body := readAll(t, resp); body != "" {
			t.Fatalf("204 carried a body: %q", body)
		}
		lines := beaconLines(buf)
		if len(lines) != 1 {
			t.Fatalf("captured %d beacon lines, want exactly 1; output:\n%s", len(lines), buf.String())
		}
		for _, field := range []string{
			"item=itm_unknown", "mode=direct", "phase=video-error",
			`code=MEDIA_ERR_SRC_NOT_SUPPORTED`, "ua=",
		} {
			if !strings.Contains(lines[0], field) {
				t.Fatalf("beacon line %q lacks %q", lines[0], field)
			}
		}
		if !strings.Contains(lines[0], "video error on the direct floor") {
			t.Fatalf("beacon line %q lacks the detail text", lines[0])
		}
	})

	t.Run("detail_truncated_to_bounded_constant", func(t *testing.T) {
		buf := captureLogs(t)
		long := strings.Repeat("x", beaconDetailLimit+50) + "TAIL-MARKER"
		body := fmt.Sprintf(`{"item_id":"itm_1","mode":"hls","phase":"fatal","code":"networkError","detail":%q}`, long)
		resp := doRequest(t, newHandler(openAPIStore(t)), http.MethodPost, "/api/v1/playback-events", body, adminToken)
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("status = %d, want 204", resp.StatusCode)
		}
		lines := beaconLines(buf)
		if len(lines) != 1 {
			t.Fatalf("captured %d beacon lines, want 1", len(lines))
		}
		if !strings.Contains(lines[0], "detail=") {
			t.Fatalf("beacon line %q lacks the detail field", lines[0])
		}
		if strings.Contains(lines[0], "TAIL-MARKER") {
			t.Fatalf("beacon line %q carried untruncated detail", lines[0])
		}
		// The logged detail is bounded: the x-run never exceeds the constant.
		if n := strings.Count(lines[0], "x"); n > beaconDetailLimit {
			t.Fatalf("logged detail run = %d chars, want <= %d", n, beaconDetailLimit)
		}
	})

	// Shape validation (D7): malformed JSON, any missing required field, and
	// out-of-vocabulary mode/phase all answer the canonical 400 bad_request
	// and log NOTHING — and none of them consumes rate budget.
	t.Run("malformed_shapes_400_and_log_nothing", func(t *testing.T) {
		buf := captureLogs(t)
		h := newHandler(openAPIStore(t))
		cases := []struct {
			name string
			body string
		}{
			{"malformed_json", `{not json`},
			{"empty_object", `{}`},
			{"missing_item_id", `{"mode":"direct","phase":"fatal","code":"c","detail":"d"}`},
			{"missing_mode", `{"item_id":"i","phase":"fatal","code":"c","detail":"d"}`},
			{"missing_phase", `{"item_id":"i","mode":"direct","code":"c","detail":"d"}`},
			{"missing_code", `{"item_id":"i","mode":"direct","phase":"fatal","detail":"d"}`},
			{"missing_detail", `{"item_id":"i","mode":"direct","phase":"fatal","code":"c"}`},
			{"bad_mode", `{"item_id":"i","mode":"dash","phase":"fatal","code":"c","detail":"d"}`},
			{"bad_phase", `{"item_id":"i","mode":"direct","phase":"warn","code":"c","detail":"d"}`},
		}
		for _, tc := range cases {
			tc := tc
			t.Run(tc.name, func(t *testing.T) {
				resp := doRequest(t, h, http.MethodPost, "/api/v1/playback-events", tc.body, adminToken)
				if resp.StatusCode != http.StatusBadRequest {
					t.Fatalf("status = %d, want 400", resp.StatusCode)
				}
				if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
					t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
				}
			})
		}
		if lines := beaconLines(buf); len(lines) != 0 {
			t.Fatalf("rejected beacons logged %d lines, want 0:\n%s", len(lines), buf.String())
		}
	})

	// No store read (D7): a nil Store in Deps must not stop the handler —
	// the unknown item_id is accepted verbatim.
	t.Run("unknown_item_accepted_with_nil_store", func(t *testing.T) {
		buf := captureLogs(t)
		resp := doRequest(t, newHandler(nil), http.MethodPost, "/api/v1/playback-events", wellFormed, adminToken)
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("status = %d, want 204 (the beacon never reads the store)", resp.StatusCode)
		}
		if lines := beaconLines(buf); len(lines) != 1 {
			t.Fatalf("captured %d beacon lines, want 1", len(lines))
		}
	})

	// Role gating: the beacon lives in the browse group, so a pairing-minted
	// client-role session (the TV) is accepted like an admin one — and a
	// tokenless request 401s via the standard middleware.
	t.Run("client_role_accepted_and_no_auth_401", func(t *testing.T) {
		st := openAPIStore(t)
		h := newHandler(st)
		client := mintClientToken(t, h)
		buf := captureLogs(t)
		resp := doRequest(t, h, http.MethodPost, "/api/v1/playback-events", wellFormed, client)
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("client-role status = %d, want 204 (the TV's voice)", resp.StatusCode)
		}
		if resp := doRequest(t, h, http.MethodPost, "/api/v1/playback-events", wellFormed, ""); resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("unauthenticated status = %d, want 401", resp.StatusCode)
		}
		if lines := beaconLines(buf); len(lines) != 1 {
			t.Fatalf("captured %d beacon lines, want 1 (the 401 logs nothing)", len(lines))
		}
	})

	// Rate limit (D7): the per-client in-process window admits exactly
	// beaconBurst, then answers 429 rate_limited — and the rejected ones log
	// NOTHING (a looping TV must not flood the log). INV4: no captured line
	// ever carries the bearer credential.
	t.Run("rate_limit_trips_to_429_and_logs_nothing_rejected", func(t *testing.T) {
		buf := captureLogs(t)
		h := newHandler(openAPIStore(t))
		accepted := 0
		for i := 0; i <= beaconBurst+2; i++ {
			resp := doRequest(t, h, http.MethodPost, "/api/v1/playback-events", wellFormed, adminToken)
			switch {
			case i < beaconBurst:
				if resp.StatusCode != http.StatusNoContent {
					t.Fatalf("beacon %d status = %d, want 204", i, resp.StatusCode)
				}
				accepted++
			default:
				if resp.StatusCode != http.StatusTooManyRequests {
					t.Fatalf("beacon %d (over limit) status = %d, want 429", i, resp.StatusCode)
				}
				if eb := decodeError(t, resp); eb.Error.Code != "rate_limited" {
					t.Fatalf("over-limit error code = %q, want rate_limited", eb.Error.Code)
				}
			}
		}
		if lines := beaconLines(buf); len(lines) != accepted {
			t.Fatalf("captured %d beacon lines for %d accepted, rejected ones must log nothing:\n%s",
				len(lines), accepted, buf.String())
		}
		if strings.Contains(buf.String(), adminToken) {
			t.Fatal("captured log carries the bearer credential (INV4)")
		}
	})
}
